-- Stage 1: legacy fields remain authoritative. No legacy value, version,
-- timestamp, event, queue intent, claim or receipt is changed by this migration.
ALTER TABLE task ADD COLUMN condition_json TEXT NOT NULL
 DEFAULT '{"kind":"clear","evidence":{"error_annotation":null,"blocked_json":null,"failed_json":null,"entry_barrier_json":null,"metadata":{},"unparsed_metadata":null}}'
 CHECK (json_valid(condition_json));

-- The correlated SELECT maps one row at a time, including malformed legacy JSON.
-- Intent/claim/receipt bodies are intentionally absent from condition evidence.
CREATE VIEW task_condition_legacy AS
-- condition-map-begin
SELECT t.id,
 (WITH raw AS (
   SELECT t.error_annotation AS a_raw, t.blocked_json AS b_raw,
          t.failed_json AS f_raw, t.entry_barrier_json AS e_raw,
          t.metadata_json AS m_raw
 ), objects AS (
   SELECT raw.*,
          CASE WHEN json_valid(a_raw) THEN CASE WHEN json_type(a_raw)='object' THEN a_raw ELSE '{}' END ELSE '{}' END AS a, CASE WHEN json_valid(b_raw) THEN CASE WHEN json_type(b_raw)='object' THEN b_raw ELSE '{}' END ELSE '{}' END AS b, CASE WHEN json_valid(f_raw) THEN CASE WHEN json_type(f_raw)='object' THEN f_raw ELSE '{}' END ELSE '{}' END AS f, CASE WHEN json_valid(e_raw) THEN CASE WHEN json_type(e_raw)='object' THEN e_raw ELSE '{}' END ELSE '{}' END AS e, CASE WHEN json_valid(m_raw) THEN CASE WHEN json_type(m_raw)='object' THEN m_raw ELSE '{}' END ELSE '{}' END AS m FROM raw
 ), parsed AS (
   SELECT objects.*, COALESCE(json_type(m,'$.deferred_dispatch')='object'
     AND json_type(m,'$.deferred_dispatch.not_before')='text'
     AND json_type(m,'$.deferred_dispatch.reason')='text'
     AND json_type(m,'$.deferred_dispatch.target_state')='text' AND (CASE WHEN json_type(m, '$.deferred_dispatch.target_state')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(m, '$.deferred_dispatch.target_state')) WHERE hex(json_extract(m, '$.deferred_dispatch.target_state')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(m, '$.deferred_dispatch.target_state') END) IS NOT NULL
     AND length(CASE WHEN json_type(m, '$.deferred_dispatch.not_before')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(m, '$.deferred_dispatch.not_before')) WHERE hex(json_extract(m, '$.deferred_dispatch.not_before')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(m, '$.deferred_dispatch.not_before') END) >= 20
     AND substr(CASE WHEN json_type(m, '$.deferred_dispatch.not_before')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(m, '$.deferred_dispatch.not_before')) WHERE hex(json_extract(m, '$.deferred_dispatch.not_before')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(m, '$.deferred_dispatch.not_before') END,11,1) IN ('T','t')
     AND strftime('%s',CASE WHEN json_type(m, '$.deferred_dispatch.not_before')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(m, '$.deferred_dispatch.not_before')) WHERE hex(json_extract(m, '$.deferred_dispatch.not_before')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(m, '$.deferred_dispatch.not_before') END) IS NOT NULL,0) AS valid_deferred
   FROM objects
 ), candidates AS (
 SELECT 0 AS ordinal, json_object('kind', 'unknown_condition', 'source', json_object('field', 'failed_json', 'key', NULL), 'problem', 'malformed_json') AS reason FROM parsed p WHERE f_raw IS NOT NULL AND NOT json_valid(f_raw)
 UNION ALL
 SELECT 1 AS ordinal, json_object('kind', 'unknown_condition', 'source', json_object('field', 'failed_json', 'key', NULL), 'problem', 'non_object') AS reason FROM parsed p WHERE f_raw IS NOT NULL AND CASE WHEN json_valid(f_raw) THEN json_type(f_raw) != 'object' ELSE 0 END
 UNION ALL
 SELECT 2 AS ordinal, json_object('kind', 'held', 'actor', COALESCE(CASE WHEN json_type(f, '$.blocked_by')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(f, '$.blocked_by')) WHERE hex(json_extract(f, '$.blocked_by')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(f, '$.blocked_by') END, 'user')) AS reason FROM parsed p WHERE f_raw IS NOT NULL AND CASE WHEN json_valid(f_raw) THEN json_type(f_raw) = 'object' ELSE 0 END AND CASE WHEN json_type(f, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(f, '$.kind')) WHERE hex(json_extract(f, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(f, '$.kind') END='manual_stop'
 UNION ALL
 SELECT 3 AS ordinal, json_object('kind', 'budget_exhausted', 'budget_kind', CASE WHEN CASE WHEN json_type(f, '$.blocking_reason')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(f, '$.blocking_reason')) WHERE hex(json_extract(f, '$.blocking_reason')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(f, '$.blocking_reason') END='review_ci_infrastructure_exhausted' THEN 'review_ci_infrastructure' ELSE CASE CASE WHEN json_type(f, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(f, '$.kind')) WHERE hex(json_extract(f, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(f, '$.kind') END WHEN 'review_budget_exhausted' THEN 'review' WHEN 'merge_fix_budget_exhausted' THEN 'merge_fix' ELSE NULL END END, 'source', json_object('field', 'failed_json', 'key', NULL)) AS reason FROM parsed p WHERE f_raw IS NOT NULL AND CASE WHEN json_valid(f_raw) THEN json_type(f_raw) = 'object' ELSE 0 END AND (CASE WHEN json_type(f, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(f, '$.kind')) WHERE hex(json_extract(f, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(f, '$.kind') END IN ('review_budget_exhausted','retry_exhausted','merge_fix_budget_exhausted') OR CASE WHEN json_type(f, '$.blocking_reason')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(f, '$.blocking_reason')) WHERE hex(json_extract(f, '$.blocking_reason')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(f, '$.blocking_reason') END='review_ci_infrastructure_exhausted')
 UNION ALL
 SELECT 4 AS ordinal, json_object('kind', 'failure', 'failure_kind', CASE WHEN json_type(f, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(f, '$.kind')) WHERE hex(json_extract(f, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(f, '$.kind') END) AS reason FROM parsed p WHERE f_raw IS NOT NULL AND CASE WHEN json_valid(f_raw) THEN json_type(f_raw) = 'object' ELSE 0 END AND CASE WHEN json_type(f, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(f, '$.kind')) WHERE hex(json_extract(f, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(f, '$.kind') END IN ('dispatch_failed','workflow_loop','cascade_failed','dependency_cancelled','merge_conflict','target_repo_dirty','dirty_worktree','ci_failed','review_gate_failed','review_budget_exhausted','review_blocked','review_needs_owner','environment_not_ready','retry_exhausted','merge_fix_budget_exhausted','workflow_guard_rejected','internal_command_failed','executor_failed','workspace_failed','workspace_reset_required','workspace_error','before_work_hook_timeout','before_work_hook_failed','max_turns_exceeded','manual_stop','recovery_required','executor_unavailable') AND CASE WHEN json_type(f, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(f, '$.kind')) WHERE hex(json_extract(f, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(f, '$.kind') END NOT IN ('manual_stop','review_budget_exhausted','retry_exhausted','merge_fix_budget_exhausted')
 UNION ALL
 SELECT 5 AS ordinal, json_object('kind', 'failure', 'failure_kind', 'workflow_loop') AS reason FROM parsed p WHERE f_raw IS NOT NULL AND CASE WHEN json_valid(f_raw) THEN json_type(f_raw) = 'object' ELSE 0 END AND CASE WHEN json_type(f, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(f, '$.kind')) WHERE hex(json_extract(f, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(f, '$.kind') END IS NULL AND 0
 UNION ALL
 SELECT 6 AS ordinal, json_object('kind', 'unknown_condition', 'source', json_object('field', 'failed_json', 'key', NULL), 'problem', 'unknown_kind') AS reason FROM parsed p WHERE f_raw IS NOT NULL AND CASE WHEN json_valid(f_raw) THEN json_type(f_raw) = 'object' ELSE 0 END AND (CASE WHEN json_type(f, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(f, '$.kind')) WHERE hex(json_extract(f, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(f, '$.kind') END IS NULL OR CASE WHEN json_type(f, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(f, '$.kind')) WHERE hex(json_extract(f, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(f, '$.kind') END NOT IN ('dispatch_failed','workflow_loop','cascade_failed','dependency_cancelled','merge_conflict','target_repo_dirty','dirty_worktree','ci_failed','review_gate_failed','review_budget_exhausted','review_blocked','review_needs_owner','environment_not_ready','retry_exhausted','merge_fix_budget_exhausted','workflow_guard_rejected','internal_command_failed','executor_failed','workspace_failed','workspace_reset_required','workspace_error','before_work_hook_timeout','before_work_hook_failed','max_turns_exceeded','manual_stop','recovery_required','executor_unavailable')) AND NOT COALESCE((0),0)
 UNION ALL
 SELECT 20 AS ordinal, json_object('kind', 'unknown_condition', 'source', json_object('field', 'blocked_json', 'key', NULL), 'problem', 'malformed_json') AS reason FROM parsed p WHERE b_raw IS NOT NULL AND NOT json_valid(b_raw)
 UNION ALL
 SELECT 21 AS ordinal, json_object('kind', 'unknown_condition', 'source', json_object('field', 'blocked_json', 'key', NULL), 'problem', 'non_object') AS reason FROM parsed p WHERE b_raw IS NOT NULL AND CASE WHEN json_valid(b_raw) THEN json_type(b_raw) != 'object' ELSE 0 END
 UNION ALL
 SELECT 22 AS ordinal, json_object('kind', 'held', 'actor', COALESCE(CASE WHEN json_type(b, '$.blocked_by')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(b, '$.blocked_by')) WHERE hex(json_extract(b, '$.blocked_by')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(b, '$.blocked_by') END, 'user')) AS reason FROM parsed p WHERE b_raw IS NOT NULL AND CASE WHEN json_valid(b_raw) THEN json_type(b_raw) = 'object' ELSE 0 END AND CASE WHEN json_type(b, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(b, '$.kind')) WHERE hex(json_extract(b, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(b, '$.kind') END='manual_stop'
 UNION ALL
 SELECT 23 AS ordinal, json_object('kind', 'budget_exhausted', 'budget_kind', CASE WHEN CASE WHEN json_type(b, '$.blocking_reason')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(b, '$.blocking_reason')) WHERE hex(json_extract(b, '$.blocking_reason')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(b, '$.blocking_reason') END='review_ci_infrastructure_exhausted' THEN 'review_ci_infrastructure' ELSE CASE CASE WHEN json_type(b, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(b, '$.kind')) WHERE hex(json_extract(b, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(b, '$.kind') END WHEN 'review_budget_exhausted' THEN 'review' WHEN 'merge_fix_budget_exhausted' THEN 'merge_fix' ELSE NULL END END, 'source', json_object('field', 'blocked_json', 'key', NULL)) AS reason FROM parsed p WHERE b_raw IS NOT NULL AND CASE WHEN json_valid(b_raw) THEN json_type(b_raw) = 'object' ELSE 0 END AND (CASE WHEN json_type(b, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(b, '$.kind')) WHERE hex(json_extract(b, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(b, '$.kind') END IN ('review_budget_exhausted','retry_exhausted','merge_fix_budget_exhausted') OR CASE WHEN json_type(b, '$.blocking_reason')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(b, '$.blocking_reason')) WHERE hex(json_extract(b, '$.blocking_reason')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(b, '$.blocking_reason') END='review_ci_infrastructure_exhausted')
 UNION ALL
 SELECT 24 AS ordinal, json_object('kind', 'failure', 'failure_kind', CASE WHEN json_type(b, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(b, '$.kind')) WHERE hex(json_extract(b, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(b, '$.kind') END) AS reason FROM parsed p WHERE b_raw IS NOT NULL AND CASE WHEN json_valid(b_raw) THEN json_type(b_raw) = 'object' ELSE 0 END AND CASE WHEN json_type(b, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(b, '$.kind')) WHERE hex(json_extract(b, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(b, '$.kind') END IN ('dispatch_failed','workflow_loop','cascade_failed','dependency_cancelled','merge_conflict','target_repo_dirty','dirty_worktree','ci_failed','review_gate_failed','review_budget_exhausted','review_blocked','review_needs_owner','environment_not_ready','retry_exhausted','merge_fix_budget_exhausted','workflow_guard_rejected','internal_command_failed','executor_failed','workspace_failed','workspace_reset_required','workspace_error','before_work_hook_timeout','before_work_hook_failed','max_turns_exceeded','manual_stop','recovery_required','executor_unavailable') AND CASE WHEN json_type(b, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(b, '$.kind')) WHERE hex(json_extract(b, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(b, '$.kind') END NOT IN ('manual_stop','review_budget_exhausted','retry_exhausted','merge_fix_budget_exhausted')
 UNION ALL
 SELECT 25 AS ordinal, json_object('kind', 'failure', 'failure_kind', 'workflow_loop') AS reason FROM parsed p WHERE b_raw IS NOT NULL AND CASE WHEN json_valid(b_raw) THEN json_type(b_raw) = 'object' ELSE 0 END AND CASE WHEN json_type(b, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(b, '$.kind')) WHERE hex(json_extract(b, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(b, '$.kind') END IS NULL AND CASE WHEN json_type(b, '$.source')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(b, '$.source')) WHERE hex(json_extract(b, '$.source')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(b, '$.source') END='workflow_loop'
 UNION ALL
 SELECT 26 AS ordinal, json_object('kind', 'unknown_condition', 'source', json_object('field', 'blocked_json', 'key', NULL), 'problem', 'unknown_kind') AS reason FROM parsed p WHERE b_raw IS NOT NULL AND CASE WHEN json_valid(b_raw) THEN json_type(b_raw) = 'object' ELSE 0 END AND (CASE WHEN json_type(b, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(b, '$.kind')) WHERE hex(json_extract(b, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(b, '$.kind') END IS NULL OR CASE WHEN json_type(b, '$.kind')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(b, '$.kind')) WHERE hex(json_extract(b, '$.kind')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(b, '$.kind') END NOT IN ('dispatch_failed','workflow_loop','cascade_failed','dependency_cancelled','merge_conflict','target_repo_dirty','dirty_worktree','ci_failed','review_gate_failed','review_budget_exhausted','review_blocked','review_needs_owner','environment_not_ready','retry_exhausted','merge_fix_budget_exhausted','workflow_guard_rejected','internal_command_failed','executor_failed','workspace_failed','workspace_reset_required','workspace_error','before_work_hook_timeout','before_work_hook_failed','max_turns_exceeded','manual_stop','recovery_required','executor_unavailable')) AND NOT COALESCE((CASE WHEN json_type(b, '$.source')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(b, '$.source')) WHERE hex(json_extract(b, '$.source')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(b, '$.source') END='workflow_loop'),0)
 UNION ALL
 SELECT 40 AS ordinal, json_object('kind', 'unknown_condition', 'source', json_object('field', 'error_annotation', 'key', NULL), 'problem', 'malformed_json') AS reason FROM parsed p WHERE a_raw IS NOT NULL AND NOT json_valid(a_raw)
 UNION ALL
 SELECT 41 AS ordinal, json_object('kind', 'unknown_condition', 'source', json_object('field', 'error_annotation', 'key', NULL), 'problem', 'non_object') AS reason FROM parsed p WHERE a_raw IS NOT NULL AND CASE WHEN json_valid(a_raw) THEN json_type(a_raw) != 'object' ELSE 0 END
 UNION ALL
 SELECT 42 AS ordinal, json_object('kind', 'held', 'actor', COALESCE(CASE WHEN json_type(a, '$.blocked_by')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(a, '$.blocked_by')) WHERE hex(json_extract(a, '$.blocked_by')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(a, '$.blocked_by') END, 'user')) AS reason FROM parsed p WHERE a_raw IS NOT NULL AND CASE WHEN json_valid(a_raw) THEN json_type(a_raw) = 'object' ELSE 0 END AND CASE WHEN json_type(a, '$.type')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(a, '$.type')) WHERE hex(json_extract(a, '$.type')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(a, '$.type') END='manual_stop'
