             WHEN valid_deferred THEN json_object('kind', 'deferred', 'until', CASE WHEN json_type(m, '$.deferred_dispatch.not_before')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(m, '$.deferred_dispatch.not_before')) WHERE hex(json_extract(m, '$.deferred_dispatch.not_before')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(m, '$.deferred_dispatch.not_before') END, 'reason', CASE WHEN json_type(m,'$.plan_settlement_wait')='object' THEN 'plan_transport' WHEN CASE WHEN json_type(a, '$.blocking_reason')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(a, '$.blocking_reason')) WHERE hex(json_extract(a, '$.blocking_reason')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(a, '$.blocking_reason') END='review_ci_infrastructure' THEN 'review_ci_infrastructure' WHEN CASE WHEN json_type(m, '$.last_workflow_guard_execution_id')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(m, '$.last_workflow_guard_execution_id')) WHERE hex(json_extract(m, '$.last_workflow_guard_execution_id')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(m, '$.last_workflow_guard_execution_id') END IS NOT NULL THEN 'workflow_guard' WHEN CASE WHEN json_type(m, '$.last_execution_failure_execution_id')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(m, '$.last_execution_failure_execution_id')) WHERE hex(json_extract(m, '$.last_execution_failure_execution_id')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(m, '$.last_execution_failure_execution_id') END IS NOT NULL THEN 'execution_failure' ELSE 'legacy' END, 'resume', json(CASE WHEN json_type(m,'$.queued_recovery')='object' THEN json_object('kind', 'resume_queued_command', 'intent_id', CASE WHEN json_type(m, '$.queued_recovery.id')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(m, '$.queued_recovery.id')) WHERE hex(json_extract(m, '$.queued_recovery.id')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(m, '$.queued_recovery.id') END) WHEN json_type(m,'$.paused_integration')='object' THEN json_object('kind', 'integrate', 'state', CASE WHEN json_type(m, '$.paused_integration.state')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(m, '$.paused_integration.state')) WHERE hex(json_extract(m, '$.paused_integration.state')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(m, '$.paused_integration.state') END) WHEN json_type(m,'$.plan_settlement_wait')='object' THEN json_object('kind', 'settle_plan', 'execution_id', CASE WHEN json_type(m, '$.plan_settlement_wait.execution_id')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(m, '$.plan_settlement_wait.execution_id')) WHERE hex(json_extract(m, '$.plan_settlement_wait.execution_id')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(m, '$.plan_settlement_wait.execution_id') END) WHEN CASE WHEN json_type(a, '$.blocking_reason')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(a, '$.blocking_reason')) WHERE hex(json_extract(a, '$.blocking_reason')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(a, '$.blocking_reason') END='review_ci_infrastructure' THEN json_object('kind', 'retry_entry', 'state', CASE WHEN json_type(e, '$.state')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(e, '$.state')) WHERE hex(json_extract(e, '$.state')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(e, '$.state') END) WHEN valid_deferred THEN json_object('kind', 'dispatch', 'target_state', CASE WHEN json_type(m, '$.deferred_dispatch.target_state')='text' AND NOT EXISTS (WITH RECURSIVE condition_utf_bytes(h) AS (SELECT hex(json_extract(m, '$.deferred_dispatch.target_state')) WHERE hex(json_extract(m, '$.deferred_dispatch.target_state')) GLOB '*ED[A-B][0-9A-F]*' UNION ALL SELECT substr(h,3) FROM condition_utf_bytes WHERE length(h)>4) SELECT 1 FROM condition_utf_bytes WHERE substr(h,1,4) GLOB 'ED[A-B][0-9A-F]') THEN json_extract(m, '$.deferred_dispatch.target_state') END) ELSE json_object('kind', 'reconcile') END), 'evidence', json(json_object('error_annotation', a_raw, 'blocked_json', b_raw, 'failed_json', f_raw, 'entry_barrier_json', e_raw, 'metadata', json(COALESCE((SELECT json_group_object(key,fragment) FROM (SELECT key, (m -> ('$.' || key)) || '' AS fragment FROM json_each(m) WHERE key IN ('awaiting_human','awaiting_human_marker_id','awaiting_human_reason','coordination_review_pending','coordination_review_pending_id','daemon_upgrade_refusal','deferred_dispatch','dispatch_disposition','environment_wait','executor_unavailable_execution_id','last_execution_failure_at','last_execution_failure_execution_id','last_workflow_guard_execution_id','last_workflow_guard_name','last_workflow_guard_reason','last_workflow_guard_rejection_at','owner_wait','paused_integration','paused_integration_generation','placement_refusal','plan_settlement_wait','planning_completed_at','planning_execution_id','planning_state_entry_token') ORDER BY key)), '{}')), 'unparsed_metadata', CASE WHEN m_raw IS NOT NULL AND NOT CASE WHEN json_valid(m_raw) THEN json_type(m_raw)='object' ELSE 0 END THEN m_raw END))) ELSE json_object('kind', 'clear', 'evidence', json(json_object('error_annotation', a_raw, 'blocked_json', b_raw, 'failed_json', f_raw, 'entry_barrier_json', e_raw, 'metadata', json(COALESCE((SELECT json_group_object(key,fragment) FROM (SELECT key, (m -> ('$.' || key)) || '' AS fragment FROM json_each(m) WHERE key IN ('awaiting_human','awaiting_human_marker_id','awaiting_human_reason','coordination_review_pending','coordination_review_pending_id','daemon_upgrade_refusal','deferred_dispatch','dispatch_disposition','environment_wait','executor_unavailable_execution_id','last_execution_failure_at','last_execution_failure_execution_id','last_workflow_guard_execution_id','last_workflow_guard_name','last_workflow_guard_reason','last_workflow_guard_rejection_at','owner_wait','paused_integration','paused_integration_generation','placement_refusal','plan_settlement_wait','planning_completed_at','planning_execution_id','planning_state_entry_token') ORDER BY key)), '{}')), 'unparsed_metadata', CASE WHEN m_raw IS NOT NULL AND NOT CASE WHEN json_valid(m_raw) THEN json_type(m_raw)='object' ELSE 0 END THEN m_raw END))) END FROM parsed p
 ) AS condition_json
 FROM task t
-- condition-map-end
;

UPDATE task SET condition_json=(SELECT condition_json FROM task_condition_legacy WHERE id=task.id);
CREATE INDEX idx_task_condition_kind ON task(json_extract(condition_json,'$.kind'));

-- Atomic adapters for ALL legacy writes, including raw SQL, INSERT and queued
-- TaskQuery/BulkTaskQuery effects. They touch only the new shadow column.
CREATE TRIGGER task_condition_insert AFTER INSERT ON task BEGIN
 UPDATE task SET condition_json=(SELECT condition_json FROM task_condition_legacy WHERE id=NEW.id) WHERE id=NEW.id;
END;
CREATE TRIGGER task_condition_legacy_update
 AFTER UPDATE OF error_annotation,blocked_json,failed_json,entry_barrier_json,metadata_json ON task
 WHEN OLD.error_annotation IS NOT NEW.error_annotation
   OR OLD.blocked_json IS NOT NEW.blocked_json OR OLD.failed_json IS NOT NEW.failed_json
   OR OLD.entry_barrier_json IS NOT NEW.entry_barrier_json OR OLD.metadata_json IS NOT NEW.metadata_json
BEGIN
 UPDATE task SET condition_json=(SELECT condition_json FROM task_condition_legacy WHERE id=NEW.id) WHERE id=NEW.id;
END;
-- Stage 1 cannot introduce a condition that disagrees with authoritative legacy
-- fields. The Rust seam also checks the Task lease, version and source snapshot.
CREATE TRIGGER task_condition_guard BEFORE UPDATE OF condition_json ON task
 WHEN NEW.condition_json IS NOT (SELECT condition_json FROM task_condition_legacy WHERE id=NEW.id)
BEGIN
 SELECT RAISE(ABORT,'task condition differs from legacy fields');
END;
